        Path worker=dir.resolve("cellbender_worker.py"),config=dir.resolve("worker-config.json");try(InputStream resource=CellBenderToolsCli.class.getResourceAsStream("/org/jlinalg/omics/cellbender_worker.py")){if(resource==null)throw new IOException("Bundled CellBender worker missing");Files.copy(resource,worker);}Files.writeString(config,RegenieRuntime.json(cfg)+"\n");protectedFiles.put(worker,hash(worker));protectedFiles.put(config,hash(config));session.put("model_config",cfg);session.put("canonical_input_sha256",protectedFiles.entrySet().stream().collect(java.util.stream.Collectors.toMap(e->e.getKey().toString(),Map.Entry::getValue)));
