        var audit=BackgroundCountsAudit.audit(dir.resolve("counts/matrix.mtx"),dir.resolve("full-corrected.mtx"),dir.resolve("filtered-corrected.mtx"),summary.features().stream().map(SparseCounts.Feature::id).toList(),summary.cells(),probabilities,filtered,csv);session.put("native_audit",Map.of("all_raw",audit.raw(),"all_corrected",audit.corrected(),"called_raw",audit.calledRaw(),"called_corrected",audit.calledCorrected(),"called",audit.called(),"analyzed",audit.analyzed()));
        var cellRows=new ArrayList<String[]>();for(var c:audit.cells())cellRows.add(new String[]{c.id(),Long.toString(c.raw()),Long.toString(c.corrected()),Long.toString(c.raw()-c.corrected()),Integer.toString(c.rawFeatures()),Integer.toString(c.correctedFeatures()),Boolean.toString(c.analyzed()),Double.isFinite(c.probability())?Double.toString(c.probability()):"NA",Boolean.toString(c.called()),Double.toString(c.removedFraction())});table(dir.resolve("cell-counts.tsv"),List.of("cell_id","raw_UMIs","corrected_UMIs","removed_UMIs","raw_features","corrected_features","model_analyzed","cell_probability","called_strict_gt_half","removed_fraction_from_immutable_raw"),cellRows);
        table(dir.resolve("feature-counts.tsv"),List.of("feature_id","raw_UMIs","corrected_UMIs","removed_UMIs"),audit.features().stream().map(f->new String[]{f.id(),Long.toString(f.raw()),Long.toString(f.corrected()),Long.toString(f.raw()-f.corrected())}).toList());
