        table(dir.resolve("results.tsv"),List.of("population","barcodes","raw_UMIs","corrected_UMIs","removed_UMIs"),List.<String[]>of(new String[]{"all_input",Integer.toString(audit.cells().size()),Long.toString(audit.raw()),Long.toString(audit.corrected()),Long.toString(audit.raw()-audit.corrected())},new String[]{"strict_gt_half_calls",Integer.toString(audit.called()),Long.toString(audit.calledRaw()),Long.toString(audit.calledCorrected()),Long.toString(audit.calledRaw()-audit.calledCorrected())},new String[]{"upstream_metric_cells_ge_half",Integer.toString(metricCells),Long.toString(metricRaw),Long.toString(metricCorrected),Long.toString(metricRaw-metricCorrected)}));
